"use client"

import * as React from "react"
import { Loader2, Server, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { checkKubeCommand, readManifests, rewriteCommand, shortCluster, type KubeContext, type KubeIssue, type ManifestObject } from "./kube"

export { checkKubeCommand, isProductionName, parseKubeCommand, readManifests, rewriteCommand, shellWords, shortCluster, type KubeCheck, type KubeCommand, type KubeContext, type KubeIssue, type ManifestObject } from "./kube"

/** Every visible string. `{context}`, `{cluster}`, `{namespace}`, `{from}`, `{to}`, `{manifest}`, `{target}`, `{current}`, `{path}` are filled in. */
export const KUBE_CONTEXT_MESSAGES = {
  context: "Context",
  namespace: "Namespace",
  prod: "Production",
  overrides: "--context in the command overrides your current context, {current}.",
  commandLabel: "Command",
  production: "This changes production ({context}).",
  dryRun: "Dry run first",
  contextChanged: "Context changed since your last command: was {from}, now {to}.",
  useContext: "Use {from}",
  defaultNamespace: "This deploys into the default namespace.",
  useNamespace: "Use {namespace}",
  mismatchKubectl: "The manifest says {manifest} but the command says {target}. kubectl will refuse this.",
  mismatchHelm: "Helm will create these objects in {manifest} but record the release in {target}.",
  elsewhere: "Objects land in {manifest} (set in the manifest), not {target}.",
  makeExplicit: "Add -n {manifest}",
  otherKubeconfig: "This reads the kubeconfig at {path}, so the context shown here may not be the one it uses.",
  typeLabel: "Type {context} to run on production",
  run: "Run on {context}",
  pending: "Running…",
  found: "{count} things to check before running.",
}

export type KubeContextMessages = typeof KUBE_CONTEXT_MESSAGES

const fill = (template: string, values: Record<string, string | number>) =>
  template.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))

export interface KubeContextGuardProps extends Omit<React.ComponentProps<"div">, "children"> {
  /** The current kubeconfig context. */
  context: KubeContext
  /** Other contexts, so a --context flag can be shown with its cluster and namespace. */
  contexts?: KubeContext[]
  /** Controlled command. */
  value?: string
  /** Initial command when uncontrolled. */
  defaultValue?: string
  /** Called with the command on every change, including one-tap fixes. */
  onValueChange?: (command: string) => void
  /** Objects being applied, or their YAML. */
  manifests?: ManifestObject[] | string
  /** Where the previous command ran, to catch a context switched in between. */
  lastRun?: { context: string; namespace?: string }
  /** Namespace to suggest instead of "default". */
  expectedNamespace?: string
  /** Your own production test. Defaults to reading context and cluster names word by word. */
  isProduction?: (context: KubeContext) => boolean
  /** Ask for the context name before a production change. */
  confirmProduction?: boolean
  /** Pause in ms before warnings refresh while typing. */
  delay?: number
  /** Called on Run. May return a Promise; shows a pending state and ignores repeat clicks. */
  onRun?: (command: string) => void | Promise<void>
  /** Any visible string. */
  messages?: Partial<KubeContextMessages>
}

/**
 * Stops kubectl and helm commands landing on the wrong cluster or namespace. It shows the context, cluster and
 * namespace the command will really use (a --context flag included) and flags production, a deploy into "default",
 * a manifest namespace that disagrees with -n (which kubectl refuses and helm silently splits), and a context that
 * changed since the last command, each with a one-tap fix.
 */
export function KubeContextGuard({
  context: current,
  contexts,
  value,
  defaultValue = "",
  onValueChange,
  manifests,
  lastRun,
  expectedNamespace,
  isProduction,
  confirmProduction = true,
  delay = 400,
  onRun,
  messages,
  className,
  ...props
}: KubeContextGuardProps) {
  const t = { ...KUBE_CONTEXT_MESSAGES, ...messages }
  const [inner, setInner] = React.useState(defaultValue)
  const command = typeof (value ?? inner) === "string" ? (value ?? inner) : ""
  const [settled, setSettled] = React.useState(command)
  const [typed, setTyped] = React.useState("")
  const [pending, setPending] = React.useState(false)
  const [status, setStatus] = React.useState("")
  const busy = React.useRef(false)
  const rootRef = React.useRef<HTMLDivElement>(null)
  const inputRef = React.useRef<HTMLInputElement>(null)
  const id = React.useId()

  React.useEffect(() => {
    const timer = setTimeout(() => setSettled(command), delay)
    return () => clearTimeout(timer)
  }, [command, delay])

  const objects = typeof manifests === "string" ? readManifests(manifests) : manifests ?? []
  const check = checkKubeCommand({ command: settled, current, contexts, manifests: objects, last: lastRun, isProduction })
  const live = checkKubeCommand({ command, current, contexts, manifests: objects, last: lastRun, isProduction })
  const ctx = live.context
  const values = { context: ctx.name, cluster: shortCluster(ctx.cluster ?? ctx.name), namespace: live.namespace, current: current?.name ?? "" }
  const needsTyping = confirmProduction && live.production && live.command.mutating
  const ready = !!command.trim() && (!needsTyping || typed.trim() === ctx.name)

  // Typing the context name is a yes to that context only.
  React.useEffect(() => setTyped(""), [ctx.name])

  React.useEffect(() => {
    setStatus(check.issues.length ? fill(t.found, { count: check.issues.length }) : "")
  }, [check.issues.length, t.found])

  const setCommand = (next: string, focusIndex?: number) => {
    if (value === undefined) setInner(next)
    setSettled(next)
    onValueChange?.(next)
    if (focusIndex === undefined) return
    requestAnimationFrame(() => {
      const fixes = rootRef.current?.querySelectorAll<HTMLElement>("[data-fix]")
      ;(fixes?.[Math.min(focusIndex, (fixes?.length ?? 1) - 1)] ?? inputRef.current)?.focus()
    })
  }

  const suggestNs = expectedNamespace || objects.find((o) => o.namespace)?.namespace
  const describe = (issue: KubeIssue): { text: string; fix?: { label: string; apply: () => string } } => {
    switch (issue.kind) {
      case "production":
        return { text: fill(t.production, values), fix: { label: t.dryRun, apply: () => rewriteCommand(command, { dryRun: true }) } }
      case "context-changed":
        return { text: fill(t.contextChanged, issue), fix: { label: fill(t.useContext, issue), apply: () => rewriteCommand(command, { context: issue.from }) } }
      case "default-namespace":
        return { text: t.defaultNamespace, fix: suggestNs ? { label: fill(t.useNamespace, { namespace: suggestNs }), apply: () => rewriteCommand(command, { namespace: suggestNs }) } : undefined }
      case "namespace-mismatch":
        return { text: fill(issue.tool === "helm" ? t.mismatchHelm : t.mismatchKubectl, issue), fix: { label: fill(t.useNamespace, { namespace: issue.manifest }), apply: () => rewriteCommand(command, { namespace: issue.manifest }) } }
      case "manifest-elsewhere":
        return { text: fill(t.elsewhere, issue), fix: { label: fill(t.makeExplicit, issue), apply: () => rewriteCommand(command, { namespace: issue.manifest }) } }
      case "other-kubeconfig":
        return { text: fill(t.otherKubeconfig, issue) }
    }
  }

  const run = async () => {
    if (!ready || busy.current || !onRun) return
    busy.current = true
    setPending(true)
    try {
      await onRun(command)
    } catch {
      // The caller reports command failures; the button becomes usable again.
    } finally {
      busy.current = false
      setPending(false)
    }
  }

  const field = "h-9 w-full min-w-0 rounded-md border bg-transparent px-3 font-mono text-base shadow-xs outline-none transition-[color,box-shadow] placeholder:text-muted-foreground/60 focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 md:text-sm dark:bg-input/30"

  return (
    <div ref={rootRef} data-slot="kube-context-guard" data-production={live.production ? "" : undefined} className={cn("w-full max-w-lg overflow-hidden rounded-xl border bg-background text-sm", className)} {...props}>
      <div
        id={`${id}-target`}
        className={cn(
          "space-y-1 border-b px-4 py-3",
          live.production ? "border-red-500/40 bg-[repeating-linear-gradient(135deg,rgb(239_68_68/0.12)_0_8px,transparent_8px_16px)]" : "bg-muted/40",
        )}
      >
        <div className="flex flex-wrap items-center gap-2">
          <Server aria-hidden className={cn("size-4 shrink-0", live.production ? "text-red-700 dark:text-red-400" : "text-muted-foreground")} />
          <span className="min-w-0 flex-1 text-base font-semibold [overflow-wrap:anywhere]">{values.cluster || "—"}</span>
          {live.production && <span className="rounded-md bg-red-700 px-1.5 py-0.5 text-xs font-semibold tracking-wide text-white uppercase dark:bg-red-500 dark:text-red-950">{t.prod}</span>}
        </div>
        <dl className="flex flex-wrap gap-x-4 gap-y-1 text-xs">
          <div className="flex min-w-0 gap-1"><dt className="text-muted-foreground">{t.context}</dt><dd className="min-w-0 font-mono [overflow-wrap:anywhere]">{ctx.name || "—"}</dd></div>
          <div className="flex min-w-0 gap-1">
            <dt className="text-muted-foreground">{t.namespace}</dt>
            <dd className={cn("min-w-0 font-mono [overflow-wrap:anywhere]", live.namespace === "default" && "font-semibold text-amber-800 dark:text-amber-300")}>{live.command.allNamespaces ? "*" : live.namespace}</dd>
          </div>
        </dl>
        {live.command.context && live.command.context !== current?.name && <p className="text-xs text-muted-foreground">{fill(t.overrides, values)}</p>}
      </div>

      <div className="space-y-3 px-4 py-3">
        <div className="grid gap-1.5">
          <label htmlFor={`${id}-cmd`} className="font-medium">{t.commandLabel}</label>
          <input
            ref={inputRef}
            id={`${id}-cmd`}
            value={command}
            onChange={(e) => setCommand(e.target.value)}
            autoComplete="off"
            autoCapitalize="off"
            spellCheck={false}
            aria-describedby={[`${id}-target`, check.issues.length ? `${id}-issues` : ""].filter(Boolean).join(" ")}
            className={field}
          />
        </div>

        {check.issues.length > 0 && (
          <ul id={`${id}-issues`} className="space-y-1.5">
            {check.issues.map((issue, i) => {
              const { text, fix } = describe(issue)
              const red = issue.kind === "production" || issue.kind === "context-changed" || issue.kind === "other-kubeconfig" || (issue.kind === "namespace-mismatch" && issue.tool === "helm")
              return (
                <li key={`${issue.kind}-${i}`} className={cn("flex flex-wrap items-start gap-x-2 gap-y-1 text-xs", red ? "text-red-800 dark:text-red-300" : "text-amber-800 dark:text-amber-300")}>
                  <span className="flex min-w-0 flex-1 basis-56 gap-1.5"><TriangleAlert aria-hidden className="mt-0.5 size-3.5 shrink-0" /><span className="min-w-0 break-words">{text}</span></span>
                  {fix && (
                    <button type="button" data-fix onClick={() => setCommand(fix.apply(), i)} className="inline-flex h-6 shrink-0 items-center rounded-md border border-current/25 px-2 text-xs font-medium outline-none transition-colors hover:bg-current/10 focus-visible:ring-[3px] focus-visible:ring-ring/50">
                      {fix.label}
                    </button>
                  )}
                </li>
              )
            })}
          </ul>
        )}

        {needsTyping && (
          <div className="grid gap-1.5">
            <label htmlFor={`${id}-type`} className="font-medium [overflow-wrap:anywhere]">{fill(t.typeLabel, values)}</label>
            <input id={`${id}-type`} value={typed} onChange={(e) => setTyped(e.target.value)} autoComplete="off" spellCheck={false} placeholder={ctx.name} className={field} />
          </div>
        )}
      </div>

      <span role="status" className="sr-only">{status}</span>
      {onRun && (
        <div className="flex justify-end border-t px-4 py-3">
          <button
            type="button"
            onClick={run}
            disabled={!ready || pending}
            aria-describedby={`${id}-target`}
            className={cn(
              "inline-flex h-9 max-w-full items-center gap-2 rounded-md px-4 text-sm font-medium outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50",
              live.production && live.command.mutating ? "bg-destructive text-white hover:bg-destructive/90" : "bg-primary text-primary-foreground hover:bg-primary/90",
            )}
          >
            {pending && <Loader2 aria-hidden className="size-4 shrink-0 animate-spin" />}
            <span className="truncate">{pending ? t.pending : fill(t.run, values)}</span>
          </button>
        </div>
      )}
    </div>
  )
}

/** The kubeconfig context a command will run against. */
export interface KubeContext {
  /** Context name (`kubectl config current-context`). */
  name: string
  /** Cluster the context points at. EKS ARNs and GKE gke_project_zone_name forms are shortened for display. */
  cluster?: string
  /** The context's default namespace; Kubernetes uses "default" when it has none. */
  namespace?: string
  /** User or auth entry. */
  user?: string
}

/** One object from the manifest being applied. */
export interface ManifestObject {
  kind: string
  name?: string
  namespace?: string
}

export interface KubeCommand {
  tool: "kubectl" | "helm" | "other"
  /** Subcommand words, e.g. ["apply"], ["rollout", "restart"], ["upgrade"]. */
  verb: string[]
  /** --context (kubectl) or --kube-context (helm) when given. */
  context?: string
  /** -n / --namespace when given (or HELM_NAMESPACE=… before a helm command). */
  namespace?: string
  /** --cluster: kubectl talks to this kubeconfig cluster whatever the context says. */
  cluster?: string
  /** --kubeconfig or a KUBECONFIG=… prefix: the command reads another kubeconfig, so the current context may not apply. */
  kubeconfig?: string
  allNamespaces: boolean
  dryRun: boolean
  /** Changes the cluster (apply, delete, scale, helm upgrade…) and isn't a dry run. */
  mutating: boolean
}

export type KubeIssue =
  | { kind: "production"; context: string }
  | { kind: "context-changed"; from: string; to: string }
  | { kind: "default-namespace" }
  | { kind: "namespace-mismatch"; manifest: string; target: string; tool: "kubectl" | "helm" }
  | { kind: "manifest-elsewhere"; manifest: string; target: string }
  | { kind: "other-kubeconfig"; path: string }

const MUTATING_KUBECTL = new Set(["apply", "create", "delete", "replace", "patch", "edit", "scale", "set", "label", "annotate", "rollout", "drain", "cordon", "uncordon", "taint", "expose", "run", "autoscale", "debug"])
// `rollout status` and `rollout history` only read.
const READ_ONLY_ROLLOUT = new Set(["status", "history"])
const MUTATING_HELM = new Set(["install", "upgrade", "uninstall", "delete", "rollback", "test"])
// Flags that take a value as the next word, so the value isn't mistaken for the subcommand.
const TAKES_VALUE = new Set([
  "-n", "--namespace", "--context", "--kube-context", "-f", "--filename", "--kubeconfig", "-o", "--output", "-l", "--selector", "--values", "-k", "--kustomize",
  "--set", "--set-string", "--set-file", "--set-json", "--version", "-c", "--container", "--cluster", "--user", "--token", "-s", "--server", "--as", "--as-group",
  "--request-timeout", "--timeout", "--cache-dir", "--certificate-authority", "--client-certificate", "--client-key", "--tls-server-name", "-p", "--patch",
  "--type", "--field-manager", "--image", "--replicas", "--repo", "--description", "--post-renderer", "--kube-apiserver", "--kube-token", "--kube-as-user",
  "--kube-as-group", "--kube-ca-file", "--registry-config", "--repository-config", "--repository-cache", "--burst-limit", "--qps",
])
// A shell operator ends the kubectl/helm part of a line (`kubectl apply -f x.yaml | tee log`).
const OPERATOR = /^(?:\||\|\||&&|;|&|>|>>|<|2>|2>&1)$/
const DEPLOY = new Set(["apply", "create", "replace", "run", "expose", "install", "upgrade"])
const CLUSTER_SCOPED = new Set([
  "namespace", "node", "persistentvolume", "clusterrole", "clusterrolebinding", "customresourcedefinition", "storageclass", "priorityclass",
  "ingressclass", "runtimeclass", "csidriver", "csinode", "apiservice", "mutatingwebhookconfiguration", "validatingwebhookconfiguration", "volumeattachment",
  "certificatesigningrequest", "validatingadmissionpolicy", "validatingadmissionpolicybinding", "clusterissuer", "podsecuritypolicy",
])

/** Splits a shell command into words, honouring quotes. */
export function shellWords(command: string) {
  const words: string[] = []
  for (const m of String(command ?? "").replace(/\\\r?\n/g, " ").matchAll(/"((?:\\.|[^"\\])*)"|'([^']*)'|(\S+)/g)) words.push(m[1] ?? m[2] ?? m[3] ?? "")
  return words
}

/** Reads the parts of a kubectl or helm command that decide where it lands. */
export function parseKubeCommand(command: string): KubeCommand {
  const words = shellWords(command)
  const start = words.findIndex((w) => /(^|\/)(kubectl|helm|k|oc)(\.exe)?$/.test(w))
  const head = start >= 0 ? words[start] : ""
  const tool: KubeCommand["tool"] = /helm(\.exe)?$/.test(head) ? "helm" : head ? "kubectl" : "other"
  const end = words.findIndex((w, i) => i > start && OPERATOR.test(w))
  const rest = start >= 0 ? words.slice(start + 1, end > start ? end : undefined) : []
  // VAR=value words right before the tool (`KUBECONFIG=~/.kube/prod kubectl …`, `HELM_NAMESPACE=x helm …`).
  const env: Record<string, string> = {}
  for (let i = start - 1; i >= 0 && /^[A-Z_][A-Z0-9_]*=/.test(words[i]); i--) env[words[i].slice(0, words[i].indexOf("="))] = words[i].slice(words[i].indexOf("=") + 1)
  const verb: string[] = []
  let context = tool === "helm" ? env.HELM_KUBECONTEXT || undefined : undefined
  let namespace = tool === "helm" ? env.HELM_NAMESPACE || undefined : undefined
  let cluster: string | undefined
  let kubeconfig = env.KUBECONFIG || undefined
  let allNamespaces = false
  let dryRun = false
  for (let i = 0; i < rest.length; i++) {
    const w = rest[i]
    if (w === "--") break
    const [flag, inline] = w.startsWith("--") && w.includes("=") ? [w.slice(0, w.indexOf("=")), w.slice(w.indexOf("=") + 1)] : [w, undefined]
    const value = () => inline ?? rest[++i]
    if (flag === "-n" || flag === "--namespace") namespace = value()
    else if (/^-n\S/.test(w)) namespace = w.slice(2).replace(/^=/, "")
    else if (flag === "--context" || flag === "--kube-context") context = value()
    else if (flag === "--cluster" && tool === "kubectl") cluster = value()
    else if (flag === "--kubeconfig") kubeconfig = value()
    else if (flag === "-A" || flag === "--all-namespaces") allNamespaces = true
    else if (flag === "--dry-run") dryRun = inline === undefined ? true : !/^(none|false)$/i.test(inline)
    else if (flag.startsWith("-")) {
      if (inline === undefined && TAKES_VALUE.has(flag)) i++
    } else if (verb.length < (verb[0] === "rollout" || verb[0] === "set" ? 2 : 1)) verb.push(w)
  }
  const readOnly = verb[0] === "rollout" && READ_ONLY_ROLLOUT.has(verb[1] ?? "")
  const mutating = !dryRun && !readOnly && (tool === "helm" ? MUTATING_HELM.has(verb[0] ?? "") : tool === "kubectl" && MUTATING_KUBECTL.has(verb[0] ?? ""))
  return { tool, verb, context, namespace, cluster, kubeconfig, allNamespaces, dryRun, mutating }
}

/** Pulls kind, name and namespace out of multi-document YAML (CRLF and BOM tolerated). Not a YAML parser; just enough to route objects. */
export function readManifests(yaml: string): ManifestObject[] {
  const out: ManifestObject[] = []
  for (const doc of String(yaml ?? "").replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n").split(/^---.*$/m)) {
    const kind = doc.match(/^kind:\s*["']?([\w.-]+)/m)?.[1]
    if (!kind) continue
    const meta = doc.match(/^metadata:[^\n]*\n((?:[ \t]+[^\n]*\n?|\n)*)/m)?.[1] ?? ""
    const indent = meta.match(/^([ \t]+)\S/)?.[1] ?? "  "
    const field = (key: string) => meta.match(new RegExp(`^${indent}${key}:\\s*["']?([^"'#\\s]+)`, "m"))?.[1]
    out.push({ kind, name: field("name"), namespace: field("namespace") })
  }
  return out
}

/** "prod-eu-1" from an EKS ARN or gke_project_zone_cluster name; anything else unchanged. */
export function shortCluster(cluster: string) {
  const c = String(cluster ?? "")
  const arn = c.match(/^arn:aws[\w-]*:eks:[^:]*:\d*:cluster\/(.+)$/)
  if (arn) return arn[1]
  const gke = c.match(/^gke_[^_]+_[^_]+_(.+)$/)
  return gke ? gke[1] : c
}

/** True for "prod", "eu-prod-2", "production", "live"; false for "nonprod", "pre-prod" and "preprod". */
export function isProductionName(name: string) {
  const words = String(name ?? "").toLowerCase().split(/[^a-z0-9]+/).filter(Boolean)
  return words.some((w, i) => /^(prod|prd|production|live)\d*$/.test(w) && !/^(pre|non|not)$/.test(words[i - 1] ?? ""))
}

export interface KubeCheck {
  command: KubeCommand
  /** The context the command will really use (its --context flag wins over current-context). */
  context: KubeContext
  /** Namespace namespaced objects without their own namespace land in. */
  namespace: string
  production: boolean
  issues: KubeIssue[]
}

/** Works out where a command lands and what's risky about it. */
export function checkKubeCommand({
  command,
  current,
  contexts = [],
  manifests = [],
  last,
  isProduction = (c: KubeContext) => isProductionName(c.name) || isProductionName(c.cluster ?? ""),
}: {
  command: string
  current: KubeContext
  contexts?: KubeContext[]
  manifests?: ManifestObject[]
  last?: { context: string; namespace?: string }
  isProduction?: (context: KubeContext) => boolean
}): KubeCheck {
  const cmd = parseKubeCommand(command)
  const safeCurrent: KubeContext = current && typeof current.name === "string" ? current : { name: "" }
  const named = cmd.context ? (contexts.find((c) => c.name === cmd.context) ?? { name: cmd.context }) : safeCurrent
  const context = cmd.cluster ? { ...named, cluster: cmd.cluster } : named
  const namespace = cmd.namespace || context.namespace || "default"
  const production = isProduction(context)
  const issues: KubeIssue[] = []
  if (production && cmd.mutating) issues.push({ kind: "production", context: context.name })
  if (cmd.kubeconfig) issues.push({ kind: "other-kubeconfig", path: cmd.kubeconfig })
  if (last?.context && last.context !== context.name) issues.push({ kind: "context-changed", from: last.context, to: context.name })
  const namespaced = (Array.isArray(manifests) ? manifests : []).filter((m) => m && typeof m.kind === "string" && !CLUSTER_SCOPED.has(m.kind.toLowerCase()))
  const pinned = [...new Set(namespaced.map((m) => m.namespace).filter((n): n is string => !!n))]
  const loose = namespaced.filter((m) => !m.namespace)
  if (cmd.mutating && !cmd.allNamespaces) {
    if (namespace === "default" && (loose.length > 0 || !namespaced.length) && DEPLOY.has(cmd.verb[0] ?? "")) issues.push({ kind: "default-namespace" })
    for (const ns of pinned) {
      if (cmd.namespace && ns !== cmd.namespace) issues.push({ kind: "namespace-mismatch", manifest: ns, target: cmd.namespace, tool: cmd.tool === "helm" ? "helm" : "kubectl" })
      else if (!cmd.namespace && ns !== namespace) issues.push({ kind: "manifest-elsewhere", manifest: ns, target: namespace })
    }
  }
  return { command: cmd, context, namespace, production, issues }
}

/** Returns the command with its namespace or context flag set (replacing any existing one), or --dry-run added. Flags go before `--`, a pipe or `&&`. */
export function rewriteCommand(command: string, change: { namespace?: string; context?: string; dryRun?: boolean }) {
  const cmd = parseKubeCommand(command)
  const full = String(command ?? "").trim()
  // Split off the tail that isn't this command's flags: `-- sh -c …` for exec, or a shell operator and what follows.
  const cut = full.search(/\s(?:--(?=\s|$)|\|\|?|&&|;|>{1,2}|2>)(?=\s|$)/)
  let out = cut >= 0 ? full.slice(0, cut) : full
  const tail = cut >= 0 ? full.slice(cut) : ""
  const quote = (s: string) => (/^[\w./:@-]+$/.test(s) ? s : `'${s.replace(/'/g, "'\\''")}'`)
  if (change.namespace !== undefined) {
    out = out.replace(/\s(?:-n|--namespace)(?:=|\s+)\S+|\s-n(?=[^\s-])\S+/g, "")
    out += ` -n ${quote(change.namespace)}`
  }
  if (change.context !== undefined) {
    out = out.replace(/\s--(?:kube-)?context(?:=|\s+)\S+/g, "")
    out += ` ${cmd.tool === "helm" ? "--kube-context" : "--context"} ${quote(change.context)}`
  }
  if (change.dryRun && !cmd.dryRun) out += cmd.tool === "helm" ? " --dry-run" : " --dry-run=server"
  return out + tail
}
